using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class LuigiPirandello
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Se lei volta la pagina, vi legge che non c'è più pazzo al mondo di chi crede d'aver ragione!", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Basta che lei si metta a gridare in faccia a tutti la verità. Nessuno ci crede, e tutti la prendono per pazza.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Chi veda soltanto una coda, facendo astrazione dal mostro a cui essa appartiene, potrà stimarla per sé stessa mostruosa. Bisognerà riattaccarla al mostro; e allora non sembrerà più tale; ma quale dev'essere, appartenendo a quel mostro. Una coda naturalissima.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "È molto più facile essere un eroe che un galantuomo. Eroi si può essere una volta tanto; galantuomini, si dev'esser sempre.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "I filosofi hanno il torto di non pensare alle bestie e davanti agli occhi di una bestia crolla come un castello di carte qualunque sistema filosofico.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Io sono nato in Sicilia e lì l'uomo nasce isola nell'isola e rimane tale fino alla morte, anche vivendo lontano dall'aspra terra natìa circondata dal mare immenso e geloso.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "L'educazione è la nemica della saggezza, perché l'educazione rende necessarie tante cose di cui, per essere saggi, si dovrebbe fare a meno.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "L'umorismo è un fenomeno di sdoppiamento nell'atto della concezione; è come un'erma bifronte, che ride per una faccia del pianto della faccia opposta.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "La cinematografia è il linguaggio di apparenze, e le apparenze non parlano. Il linguaggio delle apparenze è la musica. Bisogna levare il cinematografo dalla letteratura e metterlo nella musica, perché deve essere il linguaggio visivo della musica.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Mangia il Governo, mangia la Provincia; mangia il Comune e il capo e il sottocapo e il direttore e l'ingegnere e il sorvegliante... Che può avanzare per chi sta sotto terra e sotto di tutti e deve portar tutti sulle spalle e resta schiacciato?", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Nossignori. Per me, io sono colei che mi si crede!", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Nulla è più complicato della sincerità.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Perché civile, esser civile, vuol dire proprio questo: dentro, neri come corvi; fuori, bianchi come colombi; in corpo fiele; in bocca miele.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Quando tu riesci a non aver più un ideale, perché osservando la vita sembra un enorme pupazzata, senza nesso, senza spiegazione mai; quando tu non hai più un sentimento, perché sei riuscito a non stimare, a non curare più gli uomini e le cose, e ti manca perciò l'abitudine, che non trovi, e l'occupazione, che sdegni – quando tu, in una parola, vivrai senza la vita, penserai senza un pensiero, sentirai senza cuore – allora tu non saprai che fare: sarai un viandante senza casa, un uccello senza nido. Io sono così.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Riponi in uno stipetto un desiderio: aprilo: vi troverai un disinganno.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Sia l'urna cineraria portata in Sicilia e murata in qualche rozza pietra della campagna di Girgenti, dove nacqui.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Un poeta appassionato, malinconico, amaro, un vero e schietto e personalissimo poeta...", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Una notte di giugno caddi come una lucciola sotto un gran pino solitario in una campagna d'olivi saraceni affacciata agli orli d'un altipiano d'argille azzurre sul mare africano. Si sa le lucciole come sono. La notte, il suo nero, pare lo faccia per esse che, volando non si sa dove, ora qua ora là vi aprono un momento quel loro languido sprazzo verde.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Vorrei saper la musica per esprimere, senz'essere inteso da nessuno, neppure da Te, tutto questo tumulto di vita che mi gonfia l'anima e il cuore. Nessuno lo saprà mai, cara Marta, anche se il mio cuore ne dovesse scoppiare. Basta. Quest'esilio finirà tra poco. Salutami la Mamma e Cele, e Tu abbiti tutte le più vive cordialità dal tuo Luigi Pirandello.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Quando non vogliamo sapere una cosa – fingiamo di non saperla. – E se la finzione è più per noi stessi che per gli altri, creda pure, è proprio, proprio come se non si sapesse.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Come ci sono i figli illegittimi, ci sono anche i pensieri bastardi!", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "E non vuoi capire che la tua coscienza significa appunto \"gli altri dentro te\".", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Le donne, come i sogni, non sono mai come tu le vorresti.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Quando uno è contento di se stesso ama l'umanità.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Un angelo, per una donna, è sempre più irritante d'una bestia!", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Come a voi appajono travestiti loro, così a lui, nei nostri panni, appariremmo travestiti noi.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Ecco: quando non ci rassegniamo, vengono fuori le velleità. Una donna che vuol essere uomo... un vecchio che vuol esser giovine... – Nessuno di noi mente o finge! – C'è poco da dire: ci siamo fissati tutti in buona fede in un bel concetto di noi stessi.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Preferii restare pazzo e vivere con la più lucida coscienza la mia pazzia [...] questo che è per me la caricatura, evidente e volontaria, di quest'altra mascherata, continua, d'ogni minuto, di cui siamo i pagliacci involontari quando senza saperlo ci mascheriamo di ciò che ci par d'essere [...] Sono guarito, signori: perché so perfettamente di fare il pazzo, qua; e lo faccio, quieto! – Il guajo è per voi che la vivete agitatamente, senza saperla e senza vederla la vostra pazzia. [...] La mia vita è questa! Non è la vostra! – La vostra, in cui siete invecchiati, io non l'ho vissuta!", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Conviene a tutti, capisci? Conviene a tutti far credere pazzi certuni, per avere la scusa di tenerli chiusi. Sai perché? Perché non si resiste a sentirli parlare. […] Non si può mica credere a quello che dicono i pazzi! Eppure, si stanno ad ascoltare così, con gli occhi sbarrati dallo spavento. Perché? […] Perché trovarsi davanti a un pazzo sapete che significa? Trovarsi davanti a uno che vi scrolla dalle fondamenta tutto quanto avete costruito in voi, attorno a voi, la logica, la logica di tutte le vostre costruzioni! Eh! Che volete? Costruiscono senza logica, beati loro, i pazzi! O con una loro logica che vola come una piuma! Volubili! Volubili! Oggi così e domani chi sa come! Voi vi tenete forte, ed essi non si tengono più. Voi dite \"questo non può essere\" e per loro può essere tutto. Ma voi dite che non è vero. E perché? Perché non par vero a te, a te, a te, e centomila altri. Eh cari miei! Bisognerebbe vedere poi che cosa invece par vero a questi centomila altri che non sono detti pazzi […]. Perché guai, guai se non vi tenete forte a ciò che vi par vero oggi, a ciò che vi parrà vero domani, anche se sia l'opposto di ciò che vi pareva vero jeri!", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Confidarsi con qualcuno, questo sì, è veramente da pazzo!", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Ho paura talvolta anche del mio sangue che pulsa nelle arterie come, nel silenzio della notte, un tonfo cupo di passi in stanze lontane.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Questa cosa orribile, che fa veramente impazzire: che se siete accanto a un altro, e gli guardate gli occhi [...] potete figurarvi come un mendico davanti ad una porta in cui non potrà mai entrare: chi vi entra, non sarete mai voi, col vostro mondo dentro, come lo vedete e lo toccate; ma uno ignoto a voi, come quell'altro nel suo mondo impenetrabile vi vede e vi tocca.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Trovarsi davanti a un pazzo sapete che significa? Trovarsi davanti a uno che vi scrolla dalle fondamenta tutto quanto avete costruito in voi, attorno a voi, la logica di tutte le vostre costruzioni.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Ora sì... per forza...", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "E prese a raccontare, con atteggiamento, di grave costernazione, i fatti avvenuti di recente in Sicilia, a Serradifalco, a Catenanuova, ad Alcamo, a Casale Floresta, i quali provavano come in tutta l'isola covasse un gran fuoco, che presto sarebbe divampato; e a rappresentar la Sicilia come una catasta immane di legna, d'alberi morti per siccità, e da anni e anni abbattuti senza misericordia dall'accetta, poiché la pioggia dei benefizii s'era riversata tutta su l'Italia settentrionale, e mai una goccia ne era caduta tra le arse terre dell'isola. Ora i giovincelli s'erano divertiti ad accendere sotto la catasta i fasci di paglia delle loro predicazioni socialistiche, ed ecco che i vecchi ceppi cominciavano a prender fuoco. Erano per adesso piccoli scoppii striduli, crepitìi qua e là; scappava fuori ora da una parte ora dall'altra qualche lingua di fiamma minacciosa; ma già s'addensava nell'aria come una fumicaja soffocante. E il peggio era questo: che il Governo invece d'accorrere a gettar acqua, mandava soldati a suscitare altro fuoco col fuoco delle armi.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "E qual rovinio era sopravvenuto in Sicilia di tutte le illusioni, di tutta la fervida fede, con cui s'era accesa alla rivolta! Povera isola, trattata come terra di conquista! Poveri isolani, trattati come barbari che bisognava incivilire! Ed erano calati i Continentali a incivilirli… e i tribunali militari, e i furti, gli assassinii, le grassazioni, orditi ed eseguiti dalla nuova polizia in nome del Real Governo; e falsificazioni e sottrazioni di documenti e processi politici ignominiosi: tutto il primo governo della Destra parlamentare! E poi era venuta la Sinistra al potere, e aveva cominciato anch'essa con provvedimenti eccezionali per la Sicilia… – Ridere, ridere! – incalzò donna Caterina con più foga. – Lo sa bene anche lei come quegli ideali si sono tradotti in realtà per il popolo siciliano! Che n'ha avuto? Com'è stato trattato? Oppresso, vessato, abbandonato e vilipeso! Gli ideali del Quarantotto e del Sessanta? Ma tutti i vecchi qua gridano: Meglio prima! Meglio prima! La Francia che soffia nel fuoco? Lei si conforta così? Sono tutte calunnie, le solite, quelle che ripetono i ministri, facendo eco ai prefetti e ai tirannelli locali capielettori; per mascherare trenta e più anni di malgoverno! Qua c'è la fame, caro signore, nelle campagne e nelle zolfare; i latifondi, la tirannia feudale dei cosiddetti cappelli, le tasse comunali che succhiano l'ultimo sangue a gente che non ha neanche da comperarsi il pane! Si stia zitto! Si stia zitto! Perché voi lo vedrete, – concluse. Faccio una facile profezia: non passerà un anno, assisteremo a scene di sangue.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Dal giorno che egli, sotto l'urgenza della necessità, vincendo ogni riluttanza, dapprima con circospezione, poi risolutamente, con crudezza, le aveva detto che bisognava si recasse dal fratello Ippolito per salvare il figlio, era caduta, di schianto, in un attonimento quasi di apatia, come se la vista di tutte le cose intorno le si fosse a un tratto vuotata d'ogni senso. Non un gesto, non una parola. Più niente. E quella immobilità e quel silenzio avevano avuto fin da principio un che di così assoluto e invincibile, che né un gesto, né una parola eran più stati possibili per scuoterla o esortarla. Giulio sapeva che avrebbe ucciso la madre, parlando. E difatti, ecco, subito, parlando, l'aveva uccisa. Ella non poteva andare dal fratello per salvare il figlio: sarebbe stata la sua morte. Ed ecco, era morta.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Due cadaveri in quella cassa, uno su l'altro: uno con la faccia sotto i piedi dell'altro. Quello di sopra era d'un ragazzo. Divaricate, le gambe; la testa, affondata tra i piedi del compagno. A guardarlo così capovolto, pareva dicesse, in quell'atteggiamento: – No! No! – con tutto il visino smunto, dagli occhi appena socchiusi, contratti ancora dall'angoscia dell'agonia. No, quella morte; no, quell'orrore; no, quella cassa per due, attufata da quel lezzo crudo e acre di carneficina. La più raccapricciante era la vista dell'altro, di tra le scarpe logore del ragazzo, coi grandi occhi neri ancora sbarrati e un po' di barba fulva sotto il mento. Era d'un contadino nel pieno vigore delle forze. Con quei terribili occhi sbarrati al cielo, dal corpo supino chiedeva vendetta di quell'ultima atrocità, del peso di quell'altra vittima sopra di sé. – Vedete, Signore, – pareva dicesse, – vedete che hanno fatto!", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Sorte miserabile quella dell'eroe che non muore, dell'eroe che sopravvive a se stesso.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Invecchio, sì; perdo il gusto di comandare. Me lo fa perdere la servilità che scopro in tutti. Uomini, vorrei uomini! Mi vedo attorno automi, fantocci che devo atteggiare così o così, e che mi restano davanti, quasi a farmi dispetto, nell'atteggiamento che ho dato loro, finché non lo cambio con una manata. Soltanto di fuori però, capisci? si lasciano atteggiare! Dentro... eh, dentro, restano duri, coi loro pensieri copert, nemici, vivi solamente per loro. Che puoi su questi? Docili di fuori, miti, malleabili, visi ridenti, schiene ossequiose, t'approvano, t'approvano sempre. Ah, che sdegno! Vorrei sapere perché mi arrovello così; perché e per chi lo faccio... Domani morrò. Ho comandato! Sì, ecco: ho assegnato la parte a questo e a quello, a tanti che non hanno mai saputo veder altro in me che la parte che rappresento per loro. E di tant'altra vita, vita d'affetti e di idee che mi s'agita dentro, nessuno che abbia mai avuto il più lontano sospetto... Con chi vuoi parlarne? Sono fuori dalla parte che devo rappresentare... Certe volte, a qualcuno che viene qua a visitarmi, a incensarmi, mi diverto a rivolgere certi sguardi, certi sguardi che sfondano la parete, e me lo vedo allora per un attimo, restar davanti sospeso, impacciato, goffo; Dio sa che forza devo fare su me stesso per non scoppiargli a ridere in faccia. Mi crederebbe ammattito, per lo meno. E anche tu, caro mo, se vedessi con che occhi mi stai guardando in questo momento... – Io no! – disse subito Aurelio, riscuotendosi. Flaminio Salvo rise, scotendo il capo: – Anche tu, anche tu... È così; per forza è così... Ti posso io dire quello che vorrei veramente da te? Il piacere che mi faresti, se tu agissi com'io forse al tuo posto agirei? – E perché no? – domandò Aurelio, levandosi. – Mi dica... – Ma perché no, – negò subito il Salvo, stringendosi nelle spalle, – perché non posso... Puoi dirmi tu quel che pensi, quel che senti, la vita che hai dentro in questo momento?... Non puoi... Sei davanti a me nella relazioni che possono correre tra me e te: tu sei il mio ingegnere, il mio buon figliolo che amo, a cui questa sera, davanti a una ventina di marionette, ho dato l'incarico di recarsi a Colimbetra, messaggero di trionfo: e basta! Che altro potrei dirti? Questo soltanto, forse, per il tuo bene... E Flaminio Salvo posò una mano sulla spalla di Aurelio: – Non ti tracciar vie da seguire, figliuolo mio; né abitudini, né doveri; va', va', muoviti sempre; scròllati di tratto in tratto d'addosso ogni incrostatura di concetti; cerca il tuo piacere e non temere il giudizio degli altri e neanche il tuo, che puoi stimar giusto oggi e falso domani. Conosci don Cosmo Laurentano? Se sapessi quanta ragione ha quel matto! Va', va', è tardi; andiamo a dormire. Addio.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Non voleva credere che le banche avessero largheggiato verso il Governo per fini elettorali, per altri più loschi fini coperti; e che, favore per favore, il Governo avesse proposto leggi che per le banche erano privilegi, e difeso i prevaricatori, proponendoli agli onori della commenda e del Senato. Ma non poteva negare che fosse stato aperto il credito a certi uomini politici carezzati, che in Parlamento e per mezzo della stampa avevano combattuto a profitto delle banche falsarie, tradendo la buona fede del paese; e che questi gaudenti avessero voluto occultare ciò che da tempo si sapeva o si poteva sapere; e che, ora che le colpe avventavano, si volesse percuotere, ma con la speranza che la percossa ai più deboli salvasse i più forti.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Sapeva, sì, che già prima nelle Romagne, nel Modenese, nelle province di Reggio Emilia e di Parma, nel Cremonese, nel Mantovano, nel Polesine, era sorto a far le prime armi il socialismo italiano; ma tutt'altra cosa era adesso in Sicilia! Rivelazione improvvisa, prodigiosa!", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Un manifesto era stato attaccato ai muri, ma il popolino lo ignorava; e, ignorandolo, al solito, come altrove, coi ritratti del re e della regina, un crocefisso in capo alla processione, gridando – Viva il re! Abbasso le tasse! – s'era messo a percorrere le vie del paese, finché, uscendo dalla piazza e imboccando una strada angusta che la fronteggiava, vi aveva trovato otto soldati e quattro carabinieri appostati. L'ufficiale che li comandava aveva preso questo partito con strategia sopraffina, perché la folla inerme, lì calcata e pigiata, alle intimazioni di sbandarsi non si potesse più muovere; e lì non una ma più volte, aveva ordinato contro di essa il fuoco. Undici morti, innumerevoli feriti, tra cui donne, vecchi, bambini. Ora, tutto era calmo, come in un cimitero.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Una delle poche cose, anzi forse la sola ch'io sapessi di certo era questa: che mi chiamavo Mattia Pascal. E me ne approfittavo. Ogni qual volta qualcuno de' miei amici o conoscenti dimostrava d'aver perduto il senno fino al punto di venire da me per qualche consiglio o suggerimento, mi stringevo nelle spalle, socchiudevo gli occhi e gli rispondevo: – Io mi chiamo Mattia Pascal. – Grazie, caro. Questo lo so. – E ti par poco? Non pareva molto, per dir la verità, neanche a me. Ma ignoravo allora che cosa volesse dire il non sapere neppur questo, il non poter più rispondere, cioè, come prima, all'occorrenza: – Io mi chiamo Mattia Pascal. Qualcuno vorrà bene compiangermi (costa così poco), immaginando l'atroce cordoglio d'un disgraziato, al quale avvenga di scoprire tutt'a un tratto che... sì, niente, insomma: né padre, né madre, né come fu o come non fu; e vorrà pur bene indignarsi (costa anche meno) della corruzione dei costumi, e de' vizii, e della tristezza dei tempi, che di tanto male possono esser cagione a un povero innocente.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "E dimentichiamo spesso e volentieri di essere atomi infinitesimali per rispettarci e ammirarci a vicenda, e siamo capaci di azzuffarci per un pezzettino di terra o di dolerci di certe cose, che, ove fossimo veramente compenetrati di quello che siamo, dovrebbero parerci miserie incalcolabili.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Posso dire che da allora ho fatto il gusto a ridere di tutte le mie sciagure e d'ogni mio tormento. Mi vidi, in quell'istante, attore d'una tragedia che più buffa non si sarebbe potuta immaginare: mia madre, scappata via, così, con quella matta; mia moglie, di là, che... lasciamola stare!; Marianna Pescatore lì per terra; e io, io che non avevo più pane, quel che si dice pane, per il giorno appresso, io con la barba tutta impastocchiata, il viso sgraffiato, grondante non sapevo ancora se di sangue o di lagrime, per il troppo ridere.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "E mentr'io attenderò al molino, il fattore mi ruberà i frutti della campagna; e se mi porrò invece a badare a questa, il mugnajo mi ruberà la molenda. E di qua il mugnajo e di là il fattore faranno l'altalena, e io nel mezzo a godere.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Recisa di netto ogni memoria in me della vita precedente, fermato l'animo alla deliberazione di ricominciare da quel punto una nuova vita, io era invaso e sollevato come da una fresca letizia infantile; mi sentivo come rifatta vergine e trasparente la coscienza, e lo spirito vigile e pronto a trar profitto di tutto per la costruzione del mio nuovo io. Intanto l'anima mi tumultuava nella gioja di quella nuova libertà. Non avevo mai veduto così uomini e cose; l'aria tra essi e me s'era d'un tratto quasi snebbiata; e mi si presentavan facili e lievi le nuove relazioni che dovevano stabilirsi tra noi, poiché ben poco ormai io avrei avuto bisogno di chieder loro per il mio intimo compiacimento. Oh levità deliziosa dell'anima; serena, ineffabile ebbrezza! La Fortuna mi aveva sciolto di ogni intrico, all'improvviso, mi aveva sceverato dalla vita comune, reso spettatore estraneo della briga in cui gli altri si dibattevano ancora [...]", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Nulla s'inventa, è vero, che non abbia una qualche radice, più o men profonda, nella realtà; e anche le cose più strane possono esser vere, anzi nessuna fantasia arriva a concepire certe follie, certe inverosimili avventure che si scatenano e scoppiano dal seno tumultuoso della vita; ma pure, come e quanto appare diversa dalle invenzioni che noi possiamo trarne la realtà viva e spirante! Di quante cose sostanziali, minutissime, inimmaginabili ha bisogno la nostra invenzione per ridiventare quella stessa realtà da cui fu tratta, di quante fila che la riallaccino nel complicatissimo intrico della vita, fila che noi abbiamo recise per farla diventare una cosa a sè!", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Tu, invece, a volerla dire, sarai sempre e dovunque un forestiere: ecco la differenza. Forestiere della vita, Adriano Meis.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "C'è chi comprende e chi non comprende, caro signore. Sta molto peggio chi comprende, perché alla fine si ritrova senza energia e senza volontà. Chi comprende, infatti, dice: «Io non devo far questo, non devo far quest'altro, per non commettere questa o quella bestialità». Benissimo! Ma a un certo punto s'accorge che la vita è tutta una bestialità, e allora dica un po' lei che cosa significa il non averne commessa nessuna: significa per lo meno non aver vissuto, caro signore.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "«Oh perché gli uomini,» domandavo a me stesso, smaniosamente, «si affannano così a rendere man mano più complicato il congegno della loro vita? Perché tutto questo stordimento di macchine? E che farà l'uomo quando le macchine faranno tutto? Si accorgerà allora che il così detto progresso non ha nulla a che fare con la felicità? Di tutte le invenzioni, con cui la scienza crede onestamente d'arricchire l'umanità (e la impoverisce, perché costano tanto care), che gioja in fondo proviamo noi, anche ammirandole?»", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Eppure la scienza, pensavo; ha l'illusione di render anche più facile e più comoda L'esistenza! Ma, ammettendo che la renda veramente più facile, con tutte le sue macchine così difficili e complicate, domando, io: «E qual peggior servizio a chi sia condannato a una briga vana, che rendergliela facile e quasi meccanica?»", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Là, in un corridojo, sospesa nel vano d'una finestra, c'era una gabbia con un canarino. Non potendo con gli altri e non sapendo che fare, mi mettevo a conversar con lui, col canarino: gli rifacevo il verso con le labbra, ed esso veramente credeva che qualcuno gli parlasse e ascoltava e forse coglieva in quel mio pispissìo care notizie di nidi, di foglie, di libertà... Si agitava nella gabbia, si voltava, saltava, guardava di traverso, scotendo la testina, poi mi rispondeva, chiedeva, ascoltava ancora. Povero uccellino! lui sì m'intendeva, mentre io non sapevo che cosa gli avessi detto...", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Mi accorsi tutt'a un tratto che dovevo proprio morire ancora: ecco il male! Chi se ne ricordava più? Dopo il mio suicidio alla Stia, io naturalmente non avevo veduto più altro, innanzi a me, che la vita. Ed ecco qua, ora: il signor Anselmo Paleari mi metteva innanzi di continuo l'ombra della morte.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Il male della scienza, guardi, signor Meis, è tutto qui: che vuole occuparsi della vita soltanto.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Ma la causa vera di tutti i nostri mali, di questa tristezza nostra, sai qual è? La democrazia, mio caro, la democrazia, cioè il governo della maggioranza. Perché, quando il potere è in mano d'uno solo, quest'uno sa d'esser uno e di dover contentare molti; ma quando i molti governano, pensano soltanto a contentar se stessi, e si ha allora la tirannia più balorda e più odiosa; la tirannia mascherata da libertà.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "«Se noi riconosciamo,» pensavo, «che errare è dell'uomo, non è crudeltà sovrumana la giustizia?»", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "«Beate le marionette,» sospirai, «su le cui teste di legno il finto cielo si conserva senza strappi! Non perplessità angosciose, né ritegni, né intoppi, né ombre, né pietà; nulla! E possono attendere bravamente e prender gusto alla loro commedia e amare e tener se stesse in considerazione e in pregio, senza soffrir mai vertigini o capogiri, poiché per la loro statura e per le loro azioni quel cielo è un tetto proporzionato.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Potei sperimentare che l'uomo, quando soffre, si fa una particolare idea del bene e del male, e cioè del bene che gli altri dovrebbero fargli e a cui egli pretende, come se dalle proprie sofferenze gli derivasse un diritto al compenso, e del male che egli può fare a gli altri, come se parimenti dalle proprie sofferenze vi fosse abilitato. E se gli altri non gli fanno il bene quasi per dovere, egli li accusa, e di tutto il male ch'egli fa quasi per diritto, facilmente si scusa.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "E il signor Anselmo, seguitando, mi dimostrava che, per nostra disgrazia, noi non siamo come l'albero che vive e non si sente, a cui la terra, il sole, l'aria, la pioggia, il vento, non sembra che sieno cose ch'esso non sia: cose amiche o nocive. A noi uomini, invece, nascendo, è toccato un tristo privilegio: quello di \"sentirci\" vivere, con la bella illusione che ne risulta: di prendere cioè come una realtà fuori di noi questo nostro interno sentimento della vita, mutabile e vario, secondo i tempi, i casi e la fortuna. E questo sentimento della vita per il signor Anselmo era appunto come un lanternino che ciascuno di noi porta in sé acceso; un lanternino che ci fa vedere sperduti su la terra, e ci fa vedere il male e il bene; un lanternino che projetta tutt'intorno a noi un cerchio più o meno ampio di luce, di là dal quale è l'ombra nera, l'ombra paurosa che non esisterebbe, se il lanternino non fosse acceso in noi, ma che noi dobbiamo pur troppo creder vera, fintanto ch'esso si mantiene vivo in noi. Spento alla fine a un soffio, ci accoglierà davvero quell'ombra fittizia, ci accoglierà la notte perpetua dopo il giorno fumoso della nostra illusione, o non rimarremo noi piuttosto alla mercé dell'Essere, che avrà soltanto rotto le vane forme della nostra ragione? – Dorme, signor Meis? – Segua, segua pure, signor Anselmo: non dormo. Mi par quasi di vederlo, codesto suo lanternino. – Ah, bene... Ma poiché lei ha l'occhio offeso, non ci addentriamo troppo nella filosofia, eh? e cerchiamo piuttosto d'inseguire per ispasso le lucciole sperdute, che sarebbero i nostri lanternini, nel bujo della sorte umana. Io direi innanzi tutto che son di tanti colori; che ne dice lei? secondo il vetro che ci fornisce l'illusione, gran mercantessa, gran mercantessa di vetri colorati. A me sembra però, signor Meis, che in certe età della storia, come in certe stagioni della vita individuale, si potrebbe determinare il predominio d'un dato colore, eh? In ogni età, infatti, si suole stabilire tra gli uomini un certo accordo di sentimenti che dà lume e colore a quei lanternoni che sono in termini astratti: Verità, Virtù, Bellezza, Onore, e che so io... E non le pare che fosse rosso, ad esempio, il lanternone della Virtù pagana? Di color violetto, color deprimente, quello della Virtù cristiana. Il lume d'una idea comune è alimentato dal sentimento collettivo; se questo sentimento però si scinde, rimane sì in piedi la lanterna del termine astratto, ma la fiamma dell'idea vi crepita dentro e vi guizza e vi singhiozza, come suole avvenire in tutti i periodi che son detti di transizione. Non sono poi rare nella storia certe fiere ventate che spengono d'un tratto tutti quei lanternoni. Che piacere! Nell'improvviso bujo, allora è indescrivibile lo scompiglio delle singole lanternine: chi va di qua, chi di là, chi torna indietro, chi si raggira; nessuna più trova la via: si urtano, s'aggregano per un momento in dieci, in venti; ma non possono mettersi d'accordo, e tornano a sparpagliarsi in gran confusione, in furia angosciosa: come le formiche che non trovino più la bocca del formicajo, otturata per ispasso da un bambino crudele.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Avevo già sperimentato come la mia libertà, che a principio m'era parsa senza limiti, ne avesse purtroppo nella scarsezza del mio denaro; poi m'ero anche accorto ch'essa più propriamente avrebbe potuto chiamarsi solitudine e noja, e che mi condannava a una terribile pena: quella della compagnia di me stesso; mi ero allora accostato agli altri; ma il proponimento di guardarmi bene dal riallacciare, fors'anche debolissimamente, le fila recise, a che era valso? Ecco: s'erano riallacciate da sé, quelle fila; e la vita, per quanto io, già in guardia, mi fossi opposto, la vita mi aveva trascinato, con la sua foga irresistibile: la vita che non era più per me.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Morto? Peggio che morto; me l'ha ricordato il signor Anselmo: i morti non debbono, più morire, e io sì: io sono ancora vivo per la morte e morto per la vita. Che vita infatti può esser più la mia? La noja di prima, la solitudine, la compagnia di me stesso?", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Ma sì! così era! il simbolo, lo spettro della mia vita era quell'ombra: ero io, là per terra, esposto alla mercé dei piedi altrui. Ecco quello che restava di Mattia Pascal, morto alla Stìa: la sua ombra per le vie di Roma.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Ma aveva un cuore, quell'ombra, e non poteva amare; aveva denari, quell'ombra, e ciascuno poteva rubarglieli; aveva una testa, ma per pensare e comprendere ch'era la testa di un'ombra, e non l'ombra d'una testa. Proprio cosi!", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Ed ecco, ora, dopo essermi aggirato per due anni, come un'ombra, in quella illusione di vita oltre la morte, mi vedevo costretto, forzato, trascinato peri capelli a eseguire su me la loro condanna. Mi avevano ucciso davvero! Ed esse, esse sole si erano liberate di me... [...] Ma sì! ma sì! Io non dovevo uccider me, un morto, io dovevo uccidere quella folle, assurda finzione che m'aveva torturato, straziato due anni, quell'Adriano Meis, condannato a essere un vile, un bugiardo, un miserabile; quell'Adriano Meis dovevo uccidere, che essendo, com'era, un nome falso, avrebbe dovuto aver pure di stoppa il cervello, di cartapesta il cuore, di gomma le vene, nelle quali un po' d'acqua tinta avrebbe dovuto scorrere, invece di sangue: allora sì! Via, dunque, giù, giù, tristo fantoccio odioso! Annegato, lí, come Mattia Pascal! Una volta per uno!", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Ah, ora, ritornando vivo, avrei potuto anch'io prendermi il gusto di dire bugie, tante, tante, tante, anche della forza di quelle del cavalier Tito Lenzi, e più grosse ancora!", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Ah, che vuol dir morire! Nessuno, nessuno si ricordava più di me, come se non fossi mai esistito...", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Copernico [...] ha rovinato l'umanità, irrimediabilmente. Ormai noi tutti ci siamo a poco a poco adattati alla nuova concezione dell'infinita nostra piccolezza, a considerarci anzi men che niente nell'Universo... Storie di vermucci ormai, le nostre.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Le anime hanno un loro particolar modo d'intendersi, d'entrare in intimità, fino a darsi del tu, mentre le nostre persone sono tuttavia impacciate nel commercio delle parole comuni, nella schiavitù delle esigenze sociali. Han bisogni lor proprii e loro proprie aspirazioni le anime, di cui il corpo non si dà per inteso, quando veda l'impossibilità di soddisfarli e di tradurle in atto. E ogni qualvolta due che comunichino fra loro così, con le anime soltanto, si trovano soli in qualche luogo, provano un turbamento angoscioso e quasi una repulsione violenta d'ogni minimo contatto materiale, una sofferenza che li allontana, e che cessa subito, non appena un terzo intervenga. Allora, passata l'angoscia, le due anime sollevate si ricercano e tornano a sorridersi da lontano.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Un desiderio vago, come un'aura dell'anima, aveva schiuso pian piano per lei, come per me, una finestra nell'avvenire, donde un raggio dal tepore inebriante veniva a noi, che non sapevamo intanto appressarci a quella finestra né per richiuderla né per vedere che cosa ci fosse di là.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Vivo alla morte, ma morto alla vita.", Author = "Luigi Pirandello" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Luigi_Pirandello", Text = "Ogni oggetto in noi suol trasformarsi secondo le immagini ch'esso evoca e aggruppa, per così dire, attorno a sé. Certo un oggetto può piacere anche per se stesso, per la diversità delle sensazioni gradevoli", Author = "Luigi Pirandello" },
        };
    }
}